+static void drbd_ib_append_col_info(packet_info *pinfo, const gchar *packet_name)
+{
+    const gchar *info_text;
+
+    col_clear(pinfo->cinfo, COL_INFO);
+    info_text = col_get_text(pinfo->cinfo, COL_INFO);
+    if (!info_text || !info_text[0])
